PRAGMA foreign_keys=ON;
DROP TABLE IF EXISTS notifications; DROP TABLE IF EXISTS task_history; DROP TABLE IF EXISTS comments; DROP TABLE IF EXISTS tasks; DROP TABLE IF EXISTS memberships; DROP TABLE IF EXISTS invites; DROP TABLE IF EXISTS workspaces; DROP TABLE IF EXISTS users;
CREATE TABLE users(id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE workspaces(id INTEGER PRIMARY KEY, name TEXT NOT NULL, owner_id INTEGER NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE memberships(id INTEGER PRIMARY KEY, workspace_id INTEGER NOT NULL, user_id INTEGER NOT NULL, role TEXT NOT NULL DEFAULT 'member', UNIQUE(workspace_id,user_id), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE invites(id INTEGER PRIMARY KEY, workspace_id INTEGER NOT NULL, email TEXT NOT NULL, invited_by INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(invited_by) REFERENCES users(id));
CREATE TABLE tasks(id INTEGER PRIMARY KEY, workspace_id INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, due_date TEXT, priority TEXT NOT NULL DEFAULT 'medium', status TEXT NOT NULL DEFAULT 'todo', assignee_id INTEGER, created_by INTEGER NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(assignee_id) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE comments(id INTEGER PRIMARY KEY, task_id INTEGER NOT NULL, user_id INTEGER NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(task_id) REFERENCES tasks(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE task_history(id INTEGER PRIMARY KEY, task_id INTEGER NOT NULL, actor_id INTEGER NOT NULL, event TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(task_id) REFERENCES tasks(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, message TEXT NOT NULL, is_read INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
